            relations.append(record)
    by_file = defaultdict(list)
    for symbol in symbols:
        by_file[symbol["file_path"]].append(symbol)
    rel_index = defaultdict(set)
    for relation in relations:
        rel_index[relation["type"]].add((relation["from_id"], relation["to_id"]))
    from_index = defaultdict(set)
    for relation in relations:
        from_index[relation["type"]].add(relation["from_id"])
    return {"by_file": by_file, "files": files, "externals": externals, "rels": rel_index, "from": from_index}


