    for fact in manifest.get("absent_symbols", []):
        yield "absent_symbol", fact["tag"], f'absent {fact["file"]}#{fact["name"]}', fact
    for fact in manifest["relations"]:
        key = "|".join(types_of(fact["type"])) + " " + endpoint_key(fact["from"]) + " -> " + endpoint_key(fact["to"])
