// TestVueCorpusReactParity reports, per tag, how many facts the provider finds
// in each Vue app and in its React twin, which has the same names and call
// paths in idiomatic React. It is a report, not a ratchet: the comparable
// columns show the parity target for each Vue construct.
func TestVueCorpusReactParity(t *testing.T) {
	type row struct{ facts, vue, na, comparable, react, vueOnComparable int }
	var report strings.Builder
	for _, app := range vueCorpusApps {
		twin := loadVueCorpusTwin(t, app)
		vue := buildVueCorpusGraph(t, filepath.Join(vueCorpusRoot, app))
		react := buildVueCorpusGraph(t, filepath.Join(vueCorpusRoot, "react", app))
		rows := map[string]*row{}
		total := &row{}
		for _, fact := range vueCorpusFactsOf(loadVueCorpusManifest(t, app)) {
			r := rows[fact.Tag]
			if r == nil {
				r = &row{}
				rows[fact.Tag] = r
			}
			vueFound := vue.holds(fact, nil)
			for _, target := range []*row{r, total} {
				target.facts++
				if vueFound {
					target.vue++
				}
				if _, ok := twin.NoCounterpart[fact.Key]; ok {
					target.na++
					continue
				}
				target.comparable++
				if vueFound {
					target.vueOnComparable++
				}
			}
			if _, ok := twin.NoCounterpart[fact.Key]; !ok && react.holds(fact, twin) {
				r.react++
				total.react++
			}
		}
		tags := make([]string, 0, len(rows))
		for tag := range rows {
			tags = append(tags, tag)
		}
		sort.Strings(tags)
		fmt.Fprintf(&report, "%s: vue %d/%d, react %d/%d comparable (vue %d on the same facts)\n", app, total.vue, total.facts, total.react, total.comparable, total.vueOnComparable)
		fmt.Fprintf(&report, "  %-20s %5s %5s | %4s %10s %6s %5s\n", "tag", "facts", "vue", "n/a", "comparable", "react", "vue")
		for _, tag := range tags {
			r := rows[tag]
			fmt.Fprintf(&report, "  %-20s %5d %5d | %4d %10d %6d %5d\n", tag, r.facts, r.vue, r.na, r.comparable, r.react, r.vueOnComparable)
		}
	}
	t.Log("\n" + report.String())
}
